/** Real UI routes, motion interruption and source-conflict/privacy checks for 0.3. */
public final class TenShellSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle output=new Bundle();try{
        store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("sidebar_visible",false).putBoolean("taskbar_apps",false).putString("ten_nota_draft","").remove("ten_nota_history").remove("ten_saved_news").putString("feed_url","").putString("ten_news_mode","Auto").remove("weather_lat").commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();
        feed();taskbar(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);news();taskbar(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);news();nota();motion();sharing();
        output.putString("stream","PASS: Ten taskbar bounds on both orientations, taskbar news dashboard/bookmarks/dismissal, RSS metadata safety, window Nota selection/apply/conflict, private-context isolation, Android share/selection target, and animated minimize/restore interruption and close/reopen\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable failure){try{shot("ten-shell-failure");}catch(Exception ignored){}output.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));finish(Activity.RESULT_CANCELED,output);}}
    void feed()throws Exception{JSONArray parsed=FeedClient.parse("<rss xmlns:media='http://search.yahoo.com/mrss/'><channel><item><title>Fixture top story</title><description>News from a test feed.</description><link>https://example.com/story</link><media:thumbnail url='https://example.com/photo.jpg'/></item><item><title>Fixture second story</title><link>https://example.com/second</link></item></channel></rss>","https://example.com/feed");check(parsed.length()==2&&parsed.getJSONObject(0).getString("summary").contains("test feed")&&parsed.getJSONObject(0).getString("image").startsWith("https:"),"RSS summary and image metadata");boolean rejected=false;try{FeedClient.parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><rss/>","https://example.com");}catch(Exception expected){rejected=true;}check(rejected,"DTD is rejected");store.prefs.edit().putString("feed_items",parsed.toString()).commit();}
    void taskbar(int orientation)throws Exception{ui(()->home.setRequestedOrientation(orientation));await(()->orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?root.getHeight()>root.getWidth():root.getWidth()>root.getHeight(),"Rotation");await(()->{View bar=TenSmoke.description(root,"Desktop taskbar"),strip=root.findViewWithTag("taskbar-items");View clock=TenSmoke.description(root,"Clock and calendar");if(bar==null||strip==null||strip.getWidth()<Aero.dp(home,64)||!(clock instanceof TextView)||((TextView)clock).length()==0)return false;int[] b=new int[2];bar.getLocationOnScreen(b);for(int i=0;i<((ViewGroup)bar).getChildCount();i++){View child=((ViewGroup)bar).getChildAt(i);if(child.getVisibility()!=View.VISIBLE)continue;int[] p=new int[2];child.getLocationOnScreen(p);if(p[0]<b[0]||p[0]+child.getWidth()>b[0]+bar.getWidth()+1)return false;}return true;},"Taskbar fits with scrollable app space");shot(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?"ten-shell-taskbar-portrait":"ten-shell-taskbar-landscape");}
    void news()throws Exception{ui(()->home.open("@news"));await(()->TenSmoke.description(root,"News and interests flyout")!=null,"News opens above taskbar");ui(()->{check(!windows().containsKey("@news"),"News is a flyout, not a running window");View bookmark=TenSmoke.description(root,"Save story: Fixture top story");check(bookmark!=null,"Real feed card");bookmark.performClick();check(store.prefs.getString("ten_saved_news","").contains("Fixture top story"),"Story saved");check(TenSmoke.description(root,"News weather card")!=null,"Weather card");});shot(root.getWidth()>root.getHeight()?"ten-shell-news-landscape":"ten-shell-news-portrait");ui(home::onBackPressed);await(()->TenSmoke.description(root,"News and interests flyout")==null,"Back dismisses news");store.prefs.edit().remove("ten_saved_news").commit();ui(()->{home.open("@notes");home.open("@news");View bar=TenSmoke.description(root,"Desktop taskbar");View restore=TenSmoke.description(bar,"Minimize Notepad");if(restore==null)restore=TenSmoke.description(bar,"Restore Notepad");check(restore!=null,"Running taskbar button");restore.performClick();check(TenSmoke.description(root,"News and interests flyout")==null,"Switching a running task dismisses news");});}
    void nota()throws Exception{
        ui(()->{home.open("@notes");DesktopWindow note=windows().get("@notes");EditText editor=(EditText)TenSmoke.description(note,"Notepad text");editor.setText("The cat sleeps.");editor.setSelection(4,7);TenSmoke.description(note,"Ask Nth Nota about this window").performClick();});
        await(()->TenSmoke.find(root,TenNotaPanel.class)!=null,"Context Nota opens");
        ui(()->{TenNotaPanel panel=(TenNotaPanel)windows().get("@nota").body;check(panel.input.getText().toString().equals("cat")&&panel.pending.isEmpty(),"Only selected passage imported, no automatic request");panel.pending="apply_fixture";try{panel.result(new JSONObject().put("id","apply_fixture").put("event","result").put("text","kitten").put("local",true));}catch(Exception e){throw new RuntimeException(e);}panel.apply.performClick();});systemClick("Apply");await(()->store.prefs.getString("note","").equals("The kitten sleeps."),"Reply applied only to selected passage");
        ui(()->{TenNotaPanel panel=(TenNotaPanel)windows().get("@nota").body;EditText editor=(EditText)TenSmoke.description(windows().get("@notes"),"Notepad text");TenNotaContext source=TenNotaContext.editor("Notepad",editor);editor.setText("Newer user text");check(!source.apply("stale reply")&&editor.getText().toString().equals("Newer user text"),"Changed source cannot be overwritten");String draft=store.prefs.getString("ten_nota_draft",""),history=store.prefs.getString("ten_nota_history","");panel.context(new TenNotaContext("InPrivate selection","Private fixture passage",true));panel.pending="private_fixture";try{panel.result(new JSONObject().put("id","private_fixture").put("event","result").put("text","Private fixture reply").put("local",true));}catch(Exception e){throw new RuntimeException(e);}check(store.prefs.getString("ten_nota_draft","").equals(draft)&&store.prefs.getString("ten_nota_history","").equals(history),"Private context excluded from draft/history");});await(()->{TenNotaPanel panel=(TenNotaPanel)windows().get("@nota").body;return panel.answer.getParent() instanceof View&&((View)panel.answer.getParent()).getHeight()>=Aero.dp(home,50);},"Landscape reply has readable space");shot("ten-shell-nota-context");
    }
    void motion()throws Exception{shell("settings put global animator_duration_scale 1");try{ui(()->{store.prefs.edit().putBoolean("reduce_motion",false).commit();home.open("@calendar");});await(()->windows().get("@calendar").getWidth()>0,"Calendar laid out");ui(()->{DesktopWindow window=windows().get("@calendar");window.minimize();window.restore();});SystemClock.sleep(450);ui(()->{DesktopWindow window=windows().get("@calendar");check(window.getVisibility()==View.VISIBLE&&!window.minimizing()&&window.getAlpha()==1&&window.getScaleX()==1,"Interrupted minimize cannot hide restored window");window.closeWindow();check(window.getParent()==null,"Close removes actual window immediately");home.open("@calendar");});SystemClock.sleep(450);ui(()->check(windows().get("@calendar").getParent()!=null&&windows().get("@calendar").getAlpha()==1,"Close/reopen leaves a live visible tool"));shot("ten-shell-window-lifecycle");}finally{shell("settings put global animator_duration_scale 0");ui(()->store.prefs.edit().putBoolean("reduce_motion",true).commit());}}
    void sharing()throws Exception{Intent selection=new Intent(Intent.ACTION_PROCESS_TEXT).setType("text/plain").setComponent(new ComponentName(getTargetContext(),NotaTextActivity.class)).putExtra(Intent.EXTRA_PROCESS_TEXT,"Shared selection fixture");check(getTargetContext().getPackageManager().resolveActivity(selection,0)!=null,"Text selection target registered");ui(()->{DesktopWindow old=windows().get("@nota");if(old!=null)old.closeWindow();store.prefs.edit().putString("ten_nota_draft","").commit();home.startActivity(selection);});await(()->{DesktopWindow nota=windows().get("@nota");return nota!=null&&nota.getParent()!=null&&((TenNotaPanel)nota.body).input.getText().toString().equals("Shared selection fixture");},"Android selected text reaches Nota without a request");}
    @SuppressWarnings("unchecked") Map<String,DesktopWindow> windows(){try{Field f=MainActivity.class.getDeclaredField("windows");f.setAccessible(true);return(Map<String,DesktopWindow>)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    interface Condition {boolean get();}void check(boolean v,String why){if(!v)throw new AssertionError(why);}void ui(Runnable run)throws Exception{FutureTask<Void> task=new FutureTask<>(run,null);home.runOnUiThread(task);task.get(15,TimeUnit.SECONDS);}void await(Condition c,String why)throws Exception{long end=SystemClock.uptimeMillis()+15000;while(SystemClock.uptimeMillis()<end){FutureTask<Boolean> task=new FutureTask<>(c::get);home.runOnUiThread(task);if(task.get(10,TimeUnit.SECONDS))return;Thread.sleep(80);}throw new AssertionError(why);}
    void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(200);Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap!=null)try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    void shell(String cmd)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(cmd))){while(in.read()!=-1){}}}
    void systemClick(String text)throws Exception{long end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end){AccessibilityNodeInfo node=findNode(getUiAutomation().getRootInActiveWindow(),text);if(node!=null){android.graphics.Rect bounds=new android.graphics.Rect();node.getBoundsInScreen(bounds);long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,0,bounds.centerX(),bounds.centerY(),0),up=MotionEvent.obtain(now,now+60,1,bounds.centerX(),bounds.centerY(),0);sendPointerSync(down);sendPointerSync(up);down.recycle();up.recycle();waitForIdleSync();return;}Thread.sleep(80);}throw new AssertionError("Missing dialog action "+text);}
    AccessibilityNodeInfo findNode(AccessibilityNodeInfo node,String text){if(node==null)return null;if(text.contentEquals(node.getText()==null?"":node.getText())||text.contentEquals(node.getContentDescription()==null?"":node.getContentDescription()))return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo match=findNode(node.getChild(i),text);if(match!=null)return match;}return null;}
}
